--- support page ---
export const dynamic = "force-dynamic";

import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { SupportView } from "@/components/nx/SupportView";

/* Support, on the concept's structure.
 *
 * The concept's stat strip carries "Avg. Response Time 2m" and "99.8% Customer
 * Satisfaction". Neither is measured anywhere in this platform — there is no
 * first-response timestamp and no satisfaction survey — so neither is shown.
 * A made-up SLA figure on a support page is a promise the business has not
 * agreed to make.
 *
 * What IS measured: how many of your tickets are open, how many are waiting on
 * you, and how many closed recently. Those come straight from TicketStatus.
 */
export default async function SupportPage() {
  const user = await requireUser();
  const monthAgo = new Date(Date.now() - 30 * 86_400_000);

  const [tickets, closedRecently] = await Promise.all([
    db.ticket.findMany({
      where: { userId: user.id },
      select: {
        id: true, subject: true, status: true, priority: true,
        createdAt: true, updatedAt: true,
        messages: {
          select: { body: true, isStaff: true, createdAt: true },
          orderBy: { createdAt: "desc" },
          take: 1,
        },
      },
      orderBy: { updatedAt: "desc" },
      take: 40,
    }),
    db.ticket.count({
      where: { userId: user.id, status: "CLOSED", updatedAt: { gte: monthAgo } },
    }),
  ]);

  const rows = tickets.map((t) => ({
    id: t.id,
    subject: t.subject,
    status: t.status,
    priority: t.priority,
    updated: t.updatedAt.toISOString(),
    /* The last message, trimmed for the list. Staff or customer is marked so a
       reader can tell at a glance whose move it is. */
    preview: t.messages[0]?.body.replace(/\s+/g, " ").slice(0, 120) ?? "",
    lastFromStaff: t.messages[0]?.isStaff ?? false,
  }));

  return (
    <SupportView
      tickets={rows}
      open={rows.filter((t) => t.status !== "CLOSED").length}
      /* "Waiting for you" is ANSWERED — staff replied and the ball is in the
         customer's court. That is the state worth surfacing; it is the one they
         can act on. */
      waitingOnYou={rows.filter((t) => t.status === "ANSWERED").length}
      closedRecently={closedRecently}
    />
  );
}
